QUESTION_KINDS = ["identity", "definition", "classification", "composition", "relationship", "state", "lifecycle", "temporal", "spatial", "provenance", "ownership", "authority", "requirement", "constraint", "process", "measurement", "evidence", "quality", "validation", "security", "privacy", "retention", "access", "exception", "interoperability", "decision"]


def structure():
    bundles = []
    n = 0
    for bid, bname, bdesc, rationale, brefs, layers in STRUCTURE:
        layer_rows = []
        for lid, lname, ldesc, lrefs, findings in layers:
            finding_rows = []
            for fid, fname, fdesc, primary_kind, frefs, value_kind, required, serial in findings:
                k2 = QUESTION_KINDS[(n + 7) % len(QUESTION_KINDS)]
                k3 = QUESTION_KINDS[(n + 16) % len(QUESTION_KINDS)]
                n += 1
                questions = [
                    {"id": f"{fid}-q01", "text": f"What governed assertion is recorded for {fname.lower()}, for which subject, interest or basket, quantity, currency or unit, context and effective time?", "kind": primary_kind, "answer_data": [fname, "subject or basket and scope", "unit, context, time and status or explicit unknown"]},
                    {"id": f"{fid}-q02", "text": f"Which source, authority, method, inputs and evidence establish {fname.lower()}, with what uncertainty, quality and limitations?", "kind": k2, "answer_data": ["source and authority", "method, inputs and evidence", "uncertainty, quality and limitations"]},
                    {"id": f"{fid}-q03", "text": f"Which validation, access, reliance or change rule governs {fname.lower()}, and how are original and successor assertions preserved?", "kind": k3, "answer_data": ["validation and access rule", "authorized action and effective time", "predecessor, correction or supersession reference"]},
                ]
                data_elements = [{"id": f"{fid}-data", "name": f"{fname} assertion", "description": f"Structured price or valuation answer data for {fname.lower()}, including subject scope, unit, time, method, status and provenance.", "value_kind": value_kind, "cardinality": "1" if required else "0..n", "required": required, "source_refs": frefs}]
                artifacts = [{"id": f"{fid}-artifact", "name": f"{fname} record", "description": f"Versioned price, valuation or index record supporting {fname.lower()} with provenance and access marking.", "media_or_form": ["structured value assertion", "method or evidence statement", "resolvable evidence index"], "serial": serial, "identity_strategy": "Authoritative valuation or price master-system identifier first; otherwise a Dimension-governed UUID or ULID.", "source_refs": frefs}]
                finding_rows.append({"id": fid, "name": fname, "description": fdesc, "source_refs": frefs, "questions": questions, "data_elements": data_elements, "artifacts": artifacts, "inline_only_rationale": None})
            layer_rows.append({"id": lid, "name": lname, "description": ldesc, "source_refs": lrefs, "findings": finding_rows})
        bundles.append({"id": bid, "name": bname, "description": bdesc, "rationale": rationale, "source_refs": brefs, "layers": layer_rows})
    return {"bundles": bundles}


